From e90f6b3492aacdcc32b9a58545cc9bc3ee8bd7a8 Mon Sep 17 00:00:00 2001
From: Daniel Serpell <daniel.serpell@gmail.com>
Date: Sun, 2 Feb 2020 19:06:31 -0300
Subject: [PATCH] Update gamma values in NTSC filter presets to the new values.

This fixes issue #89, introduced in commit 5f6d891ac1023917133c2ec560dad3eaa27e90d7

diff --git a/src/atari_ntsc/atari_ntsc.c b/src/atari_ntsc/atari_ntsc.c
index 52a4597b..1efa7f5b 100644
--- a/src/atari_ntsc/atari_ntsc.c
+++ b/src/atari_ntsc/atari_ntsc.c
@@ -16,10 +16,10 @@ Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301 USA */

 /* Atari change: removal and addition of structure fields.
    Values of resolution and sharpness adjusted to make NTSC artifacts look better. */
-atari_ntsc_setup_t const atari_ntsc_monochrome = { 0, -1, 0, 0, -.3,  .3,  .2, -.2, -.2, -1, 0, 0, 0, 0. };
-atari_ntsc_setup_t const atari_ntsc_composite  = { 0,  0, 0, 0, -.5,  .3, -.1,   0,   0,  0, 0, 0, 0, 0. };
-atari_ntsc_setup_t const atari_ntsc_svideo     = { 0,  0, 0, 0, -.3,  .3,  .2,  -1,  -1,  0, 0, 0, 0, 0. };
-atari_ntsc_setup_t const atari_ntsc_rgb        = { 0,  0, 0, 0, -.3,  .3,  .7,  -1,  -1, -1, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_monochrome = { 0, -1, 0, 0, -.3,  2.35,  .2, -.2, -.2, -1, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_composite  = { 0,  0, 0, 0, -.5,  2.35, -.1,   0,   0,  0, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_svideo     = { 0,  0, 0, 0, -.3,  2.35,  .2,  -1,  -1,  0, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_rgb        = { 0,  0, 0, 0, -.3,  2.35,  .7,  -1,  -1, -1, 0, 0, 0, 0. };

 #define alignment_count 4
 #define burst_count     1
-- 
2.25.1

The code statements that lead to the bug are:
```c
-atari_ntsc_setup_t const atari_ntsc_monochrome = { 0, -1, 0, 0, -.3,  .3,  .2, -.2, -.2, -1, 0, 0, 0, 0. };
-atari_ntsc_setup_t const atari_ntsc_composite  = { 0,  0, 0, 0, -.5,  .3, -.1,   0,   0,  0, 0, 0, 0, 0. };
-atari_ntsc_setup_t const atari_ntsc_svideo     = { 0,  0, 0, 0, -.3,  .3,  .2,  -1,  -1,  0, 0, 0, 0, 0. };
```
Reason:
The outdated gamma values (e.g., `.3`) in the NTSC filter presets were not aligned with the expected new values, leading to incorrect visual output when processing NTSC signals.

The code statements that fix the bug are:
```c
+atari_ntsc_setup_t const atari_ntsc_monochrome = { 0, -1, 0, 0, -.3,  2.35,  .2, -.2, -.2, -1, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_composite  = { 0,  0, 0, 0, -.5,  2.35, -.1,   0,   0,  0, 0, 0, 0, 0. };
+atari_ntsc_setup_t const atari_ntsc_svideo     = { 0,  0, 0, 0, -.3,  2.35,  .2,  -1,  -1,  0, 0, 0, 0, 0. };
```
Reason:
The gamma values have been updated to the new values (e.g., `2.35`), which align with the expected values, thus correcting the visual output when processing NTSC signals.

